# Logo CENADURIA VICKY pre-renderizado en ESC/POS (Modo universal ESC * 24-dot double density)
# Generado para maxima compatibilidad con impresoras termicas clon (Kinwodon POS-8360 / Xprinter / Epson)
import base64

LOGO_WIDTH = 288
LOGO_HEIGHT = 288
LOGO_MODE = "ESC_STAR_24DOT"

# Bytecode base64 pre-calculado para impresion instantanea sin latencia de renderizado
_LOGO_B64 = ""

def get_logo_bytes() -> bytes:
    """Retorna los bytes ESC/POS listos para enviar directo al buffer de la impresora."""
    return base64.b64decode(_LOGO_B64)
